<dialog x-ref="editorDialog" aria-labelledby="mf-dialog-title" @cancel.prevent="closeDialog()">
    <div class="mf-dialog-shell">
        <header class="border-b p-4 flex items-center justify-between gap-3">
            <div><h2 id="mf-dialog-title" class="font-bold" x-text="({'crew-pick':'Pilih kru organisasi','crew-new':'Buat kru baru','crew-edit':'Profil & penugasan kru','location-new':'Tambah lokasi','location-edit':'Detail lokasi','location-point':'Titik lokasi','location-readiness':'Kesiapan lokasi','crew-availability':'Ketersediaan kru','location-availability':'Ketersediaan lokasi','day-new':'Tambah hari call sheet','day-edit':'Editor call sheet','sheet-preview':'Preview call sheet'})[mode] || 'Editor proyek'"></h2><p class="mf-muted" x-text="capabilities?.organization?.name"></p></div>
            <button type="button" class="mf-btn" aria-label="Tutup editor" :disabled="busy" @click="closeDialog()">✕</button>
        </header>
        <div class="mf-dialog-body space-y-5">
            <p x-show="loading" role="status" class="animate-pulse">Memuat…</p>
            <div x-show="error && mode" role="alert" class="bg-red-50 border border-red-200 rounded-xl p-3 text-sm text-red-800"><p x-text="error"></p><template x-for="(message,path) in fields" :key="path"><p x-text="fieldLabel(path) + ': ' + message"></p></template></div>
            <label x-show="pending?.photoRequired && !photo">Pilih ulang foto yang sama<input type="file" accept="image/png,image/jpeg,image/webp" @change="choosePhoto($event)"></label>
            <div x-show="pending" class="bg-amber-50 p-3 rounded-xl text-sm">Hasil operasi belum pasti. Ulangi penyimpanan yang sama sebelum melakukan perubahan lain.<button type="button" class="mf-btn mt-2" :disabled="busy" @click="mutate(pending,photo)">Ulangi operasi yang sama</button></div>
            <div x-show="remoteChanged" class="bg-amber-50 p-3 rounded-xl text-sm space-y-2"><p>Ada perubahan dari Mufise. Draf Anda tetap tersimpan.</p><button type="button" class="mf-btn" :disabled="loading || busy || !!pending" @click="reviewLatest()">Tinjau versi terbaru</button></div>
            <div x-show="latest" class="space-y-3 overflow-x-auto"><table class="w-full text-xs border"><thead><tr><th class="p-2 text-left">Isian</th><th class="p-2 text-left">Terbaru di Mufise</th><th class="p-2 text-left">Draf Anda</th></tr></thead><tbody><template x-for="row in comparison" :key="row.key"><tr class="border-t"><th class="p-2 text-left" x-text="row.key"></th><td class="p-2 max-w-xs break-words" x-text="row.current"></td><td class="p-2 max-w-xs break-words" x-text="row.draft"></td></tr></template></tbody></table><button type="button" class="mf-btn" @click="acceptLatest()">Sudah ditinjau · pertahankan perubahan saya</button></div>
            <template x-if="mode === 'sheet-preview'"><iframe sandbox :src="media('call-sheets/' + target,'html')" title="Preview call sheet Mufise" class="w-full border rounded-lg" style="height:65vh"></iframe></template>
            <fieldset :disabled="!mode || busy || loading || !!pending" class="space-y-5">
                <template x-if="mode === 'crew-pick'"><div class="space-y-4">
                    <template x-if="!person"><div class="space-y-3">
                        <label>Cari nama, jabatan atau departemen<input type="search" x-model="query" @input.debounce.350ms="page=1;searchCrew()" placeholder="Cari kru organisasi" autofocus></label>
                        <p x-show="searching" role="status">Mencari kru…</p>
                        <template x-for="personOption in directory" :key="personOption.id"><button type="button" class="w-full border rounded-xl p-3 flex gap-3 text-left" @click="selectPerson(personOption)"><img x-show="personOption.has_photo" :src="personOption.has_photo ? media('organization-crew/' + personOption.id + '/photo') : ''" alt="" class="w-12 h-12 rounded-full object-cover"><span><span class="block font-semibold" x-text="personOption.full_name"></span><span class="mf-muted block" x-text="(personOption.positions || []).map(p=>p.name).join(' · ')"></span><span x-show="personOption.registered_account" class="text-xs text-sky-700">Akun terdaftar</span><span class="mf-muted block" x-text="(personOption.assignments || []).map(a=>a.role).join(', ')"></span></span></button></template>
                        <p x-show="!searching && !directory.length" class="mf-muted">Belum ada hasil. Coba kata lain atau buat kru baru.</p>
                        <div class="flex gap-2"><button type="button" class="mf-btn" :disabled="page === 1 || searching" @click="page--;searchCrew()">Sebelumnya</button><span class="mf-muted self-center" x-text="'Halaman ' + page"></span><button type="button" class="mf-btn" :disabled="!hasMore || searching" @click="page++;searchCrew()">Berikutnya</button><button type="button" class="mf-btn" @click="open('crew-new')">Buat kru baru</button></div>
                    </div></template>
                    <template x-if="person"><div class="space-y-3"><p class="font-semibold" x-text="person.full_name"></p><p class="mf-muted">Keahlian: <span x-text="(person.positions || []).map(p=>p.name).join(', ')"></span></p><label>Konfirmasikan jabatan produksi<select x-model="form.position_id" @change="touch()"><option value="">Pilih jabatan</option><template x-for="position in positions" :key="position.id"><option :value="position.id" :disabled="assigned(position)" x-text="position.name + (assigned(position) ? ' · sudah ditugaskan' : '')"></option></template></select></label><button type="button" class="mf-btn" @click="person=null;form={};dirty=false">Pilih orang lain</button></div></template>
                </div></template>
                <template x-if="mode === 'crew-new' || (mode === 'crew-edit' && detail?.profile)"><div class="space-y-4">
                    <template x-if="mode === 'crew-edit'"><div class="space-y-2"><img x-show="detail.photo_path" :src="detail.photo_path ? media('crew/' + target + '/photo') : ''" alt="Foto kru" class="w-20 h-20 object-cover rounded-full"><p x-show="detail.profile.registered_account" class="text-xs text-sky-700">Akun terdaftar · Email dan telepon dikelola pemilik melalui profil Mufise.</p><div x-show="!detail.permissions.can_edit_identity" class="grid sm:grid-cols-2 gap-3 text-sm"><p>Telepon: <span x-text="detail.profile.phone || '—'"></span></p><p>Email: <span x-text="detail.profile.email || '—'"></span></p></div><p class="mf-muted">Profil personel dipakai lintas penugasan. Koreksi memerlukan alasan.</p></div></template>
                    <fieldset :disabled="mode === 'crew-edit' && (!permission('can_edit_crew') || !detail?.permissions?.can_edit)" class="grid sm:grid-cols-2 gap-4" @input="touch()">
                        <label>Nama lengkap<input x-model="form.full_name" maxlength="120" :aria-invalid="!!fields.full_name" required></label>
                        <label>Nama panggung<input x-model="form.stage_name" maxlength="120"></label>
                        <template x-if="mode === 'crew-new' || detail?.permissions?.can_edit_identity"><div class="contents"><label>Telepon<input x-model="form.phone" maxlength="30" :required="mode === 'crew-new'" :aria-invalid="!!fields.phone"></label><label>Email<input type="email" x-model="form.email" maxlength="255" :aria-invalid="!!fields.email"></label></div></template>
                        <label class="sm:col-span-2">Alamat<input x-model="form.address" maxlength="500"></label>
                        <label class="sm:col-span-2">Filmografi<textarea rows="3" maxlength="3000" x-model="form.filmography"></textarea></label>
                        <label class="sm:col-span-2">Foto (PNG, JPEG, WebP · maks. 5 MB)<input type="file" accept="image/png,image/jpeg,image/webp" @change="choosePhoto($event)"></label>
                    </fieldset>
                    <template x-if="mode === 'crew-new'"><div class="space-y-4">
                        <div><p class="text-sm font-medium mb-2">Keahlian</p><div class="grid sm:grid-cols-2 gap-2 max-h-40 overflow-auto border rounded-lg p-3"><template x-for="position in positions" :key="position.id"><label class="flex gap-2"><input type="checkbox" :value="position.id" x-model="form.position_ids" @change="touch()"><span x-text="position.name"></span></label></template></div></div>
                        <label>Jabatan pada proyek<select x-model="form.position_id" @change="touch()"><option value="">Konfirmasikan jabatan</option><template x-for="position in positions.filter(p => form.position_ids.includes(p.id))" :key="position.id"><option :value="position.id" x-text="position.name"></option></template></select></label>
                        <button type="button" class="mf-btn" @click="previewCrew()">Periksa duplikat</button>
                        <template x-if="preview"><div class="bg-sky-50 p-3 rounded-xl space-y-3"><p class="text-sm" x-text="preview.action === 'create' ? 'Tidak ditemukan duplikat. Siap disimpan.' : 'Tinjau personel berikut sebelum melanjutkan.'"></p><template x-for="candidate in [...(preview.duplicates || []), ...(preview.similar || [])]" :key="candidate.id"><button type="button" class="mf-btn" @click="selectPerson(candidate)" x-text="'Pilih ' + (candidate.full_name || candidate.name)"></button></template><label x-show="preview.action === 'confirm_distinct'"><input type="checkbox" x-model="form.confirm_distinct" @change="storeDraft()"> Saya telah meninjau; ini orang yang berbeda.</label></div></template>
                    </div></template>
                    <template x-if="mode === 'crew-edit'"><div class="space-y-3"><label x-show="detail.permissions.can_edit_assignment">Jabatan produksi<select x-model="form.position_id" :disabled="!permission('can_edit_crew')" @change="touch()"><option value="">Pertahankan jabatan</option><template x-for="position in positions" :key="position.id"><option :value="position.id" x-text="position.name"></option></template></select></label><label x-show="permission('can_edit_crew') && detail.permissions.can_edit">Alasan perubahan<input x-model="form.reason" minlength="3" maxlength="500" @input="touch()"></label><div class="flex gap-2 flex-wrap"><button type="button" class="mf-btn" @click="availabilityForm('crew')">Ketersediaan kru</button><button type="button" x-show="permission('can_remove_crew')" class="mf-btn text-red-700" @click="removeCrew()">Lepas penugasan</button></div></div></template>
                </div></template>
                <template x-if="mode === 'location-new' || (mode === 'location-edit' && detail?.location)"><div class="space-y-4">
                    <fieldset :disabled="!permission('can_edit_locations')" class="grid sm:grid-cols-2 gap-4" @input="touch()">
                        <template x-for="key in ['name','address','parking','hospital']" :key="key"><label><span x-text="fieldLabel(key)"></span><input x-model="form[key]" maxlength="500" :required="['name','address'].includes(key)" :aria-invalid="!!fields[key]"></label></template>
                    </fieldset>
                    <template x-if="mode === 'location-new'"><div class="space-y-3"><p class="text-sm">Titik lokasi · opsional</p><div class="flex gap-2 flex-wrap"><template x-for="kind in ['shoot','parking','hospital']" :key="kind"><button type="button" class="mf-btn" @click="addPoint(kind)" x-text="({shoot:'Syuting',parking:'Parkir',hospital:'Rumah sakit'})[kind]"></button></template></div><template x-for="(point,index) in form.points" :key="point.kind"><div class="border rounded-lg p-3 space-y-3"><p class="text-sm font-semibold" x-text="({shoot:'Syuting',parking:'Parkir',hospital:'Rumah sakit'})[point.kind]"></p><div class="grid grid-cols-2 gap-3"><label>Latitude<input type="number" step="any" min="-85.05112878" max="85.05112878" x-model.number="point.latitude" @input="touch()"></label><label>Longitude<input type="number" step="any" min="-180" max="180" x-model.number="point.longitude" @input="touch()"></label><label>Nama titik<input x-model="point.name" @input="touch()"></label><label>Alamat titik<input x-model="point.address" @input="touch()"></label></div><iframe x-show="mapUrl(point)" :src="mapEmbed(point)" title="Pin lokasi pada OpenStreetMap" loading="lazy" class="w-full h-48 border rounded-lg"></iframe><a x-show="mapUrl(point)" :href="mapUrl(point)" target="_blank" rel="noopener noreferrer" class="text-xs underline">Lihat pin di OpenStreetMap ↗</a><button type="button" class="mf-btn" @click="form.points.splice(index,1);touch()">Hapus titik</button></div></template></div></template>
                    <template x-if="mode === 'location-edit'"><div class="space-y-4">
                        <div><h3 class="font-semibold text-sm mb-2">Titik lokasi</h3><div class="flex gap-2 flex-wrap"><template x-for="kind in ['shoot','parking','hospital']" :key="kind"><button type="button" class="mf-btn" @click="pointForm(kind)" x-text="({shoot:'Syuting',parking:'Parkir',hospital:'Rumah sakit'})[kind]"></button></template></div></div>
                        <div><h3 class="font-semibold text-sm mb-2">Kesiapan · Check → Recce → Lock</h3><p class="mf-muted mb-2">Lock lokasi berbeda dari kunci hari call sheet.</p><div class="grid grid-cols-3 gap-2"><template x-for="step in ['check','recce','lock']" :key="step"><button type="button" class="mf-btn flex-col" @click="readinessForm(step)"><span x-text="step"></span><span class="mf-muted" x-text="(detail.readiness || []).find(r=>r.step===step)?.status || 'pending'"></span><span class="mf-muted" x-text="(detail.readiness || []).find(r=>r.step===step)?.completed_on || ''"></span></button></template></div></div>
                        <p class="mf-muted" x-text="'Scene terkait: ' + (detail.linked_scenes || []).map(s=>s.number).join(', ')"></p>
                        <button type="button" class="mf-btn" @click="availabilityForm('location')">Ketersediaan lokasi</button>
                    </div></template>
                </div></template>
                <template x-if="mode === 'location-point'"><fieldset class="space-y-4" :disabled="!permission('can_edit_locations')" @input="touch()"><p class="mf-muted">Pilih pin melalui tautan peta atau isi koordinat. Pencarian alamat tidak wajib.</p><div x-show="capabilities.features.geocoding_configured" class="space-y-2"><label>Cari alamat<input x-model="geoQuery" minlength="3" maxlength="120"></label><button type="button" class="mf-btn" @click="geocode()">Cari alamat</button><template x-for="(result,index) in geoResults" :key="index"><button type="button" class="mf-btn" @click="form.latitude=Number(result.latitude);form.longitude=Number(result.longitude);form.address=result.address || result.label || '';touch()" x-text="result.label || result.address || result.name"></button></template></div><div class="grid grid-cols-2 gap-3"><label>Latitude<input type="number" step="any" min="-85.05112878" max="85.05112878" x-model.number="form.latitude"></label><label>Longitude<input type="number" step="any" min="-180" max="180" x-model.number="form.longitude"></label></div><label>Nama titik<input x-model="form.name"></label><label>Alamat<input x-model="form.address"></label><iframe x-show="mapUrl(form)" :src="mapEmbed(form)" title="Pin lokasi pada OpenStreetMap" loading="lazy" class="w-full h-56 border rounded-lg"></iframe><a x-show="mapUrl(form)" :href="mapUrl(form)" target="_blank" rel="noopener noreferrer" class="mf-btn">Lihat pin di OpenStreetMap ↗</a><p class="mf-muted">Peta © kontributor OpenStreetMap</p></fieldset></template>
                <template x-if="mode === 'location-readiness'"><fieldset class="space-y-4" :disabled="!permission('can_edit_locations')" @input="touch()"><p class="text-sm" x-text="'Tahap ' + readinessStep"></p><label>Status<select x-model="form.status"><option value="pending">Belum dimulai</option><option value="in_progress">Dikerjakan</option><option value="done">Selesai</option></select></label><label>Tanggal selesai<input type="date" x-model="form.completed_on" :required="form.status === 'done'"></label><label>Penanggung jawab<select x-model="form.owner_user_id"><option :value="null">Belum ditentukan</option><template x-for="owner in detail.owners || []" :key="owner.user_id"><option :value="owner.user_id" x-text="owner.name"></option></template></select></label><label>Catatan<textarea x-model="form.notes" rows="3"></textarea></label><p class="mf-muted">Tahap berikutnya memerlukan tahap sebelumnya selesai. Menurunkan status dapat mereset tahap lanjut.</p></fieldset></template>
                <template x-if="mode.endsWith('-availability')"><div class="space-y-4"><div class="text-sm space-y-1"><p class="font-semibold">Rentang tidak tersedia</p><template x-for="(range,index) in availability" :key="index"><p x-text="[range.date,range.end_date,range.reason].filter(Boolean).join(' · ')"></p></template><p x-show="!availability.length" class="mf-muted">Belum ada rentang tidak tersedia.</p></div><div class="grid sm:grid-cols-2 gap-3" @input="touch()"><label>Tanggal mulai<input type="date" x-model="form.date"></label><label>Sampai tanggal<input type="date" x-model="form.end_date" :min="form.date"></label><label class="sm:col-span-2">Alasan<input x-model="form.reason" maxlength="500"></label></div></div></template>
                @include('frontend.mufise.editor-day')
            </fieldset>
        </div>
        <footer class="border-t p-4 bg-white flex gap-2 justify-end flex-wrap">
            <a :href="directUrl()" target="_blank" rel="noopener noreferrer" class="mf-btn">Buka di Mufise ↗</a>
            <button type="button" class="mf-btn" :disabled="busy" @click="closeDialog()">Tutup</button>
            <button type="button" x-show="canSave()" class="mf-btn mf-primary" :disabled="busy || loading || remoteChanged || (mode === 'crew-pick' && !form.position_id)" @click="save()" x-text="busy ? 'Menyimpan…' : pending ? 'Ulangi penyimpanan' : 'Simpan ke Mufise'"></button>
        </footer>
    </div>
</dialog>
